descriptor.controllerScript:
// ===================== Kuvio - Vídeo tutorial flotante =====================
// Se coloca (en pequeño y transparente) en el estado del dashboard que tenga tutorial.
// Muestra un aviso fijo abajo a la derecha de la pantalla con un botón que abre el
// vídeo en grande. Con la × se minimiza a un botón redondo (no desaparece del todo).
// Cada vez que se entra al estado o se recarga la página vuelve a salir la tarjeta completa.
// Dentro de un diálogo no se muestra (ya lo muestra el estado de detrás).
//
// QUÉ VÍDEO ABRE: según el TÍTULO del widget (Editar widget > Título; el título
// puede quedar oculto con "Mostrar título" desactivado).
//   - título que contenga "grupos"  -> vídeo de Grupos de riego
//   - título que contenga "gemelo"  -> vídeo del Gemelo digital
//   - cualquier otro título         -> ventana con todos los vídeos en pestañas
// Direcciones válidas: Google Drive (compartido "Cualquier persona con el enlace"),
// YouTube (oculto), Vimeo o un .mp4 directo.
//
// MANUAL EN PDF: pega en 'manual' el enlace de Google Drive del PDF (compartido
// "Cualquier persona con el enlace") o la dirección directa de un .pdf.
// Si 'manual' está vacío, no se muestra el botón de descarga.

var VIDEOS = [
    { clave: 'grupos', titulo: 'Grupos de riego: caudales', url: 'https://drive.google.com/file/d/1b3BGZoHYPs_mKteaWd6UGldp3T57c-b5/view?usp=drive_link',
      manual: 'https://drive.google.com/file/d/1sggNhla0zFzDpEaQV6M5duS7NYFiOnQy/view?usp=sharing' /* Calendario de caudales - Manual de uso.pdf */ },
    { clave: 'gemelo', titulo: 'Gemelo digital de riego',   url: 'https://drive.google.com/file/d/13IOdriNmz1EkPLG17VcQ6R2iZbXi_4T1/view?usp=sharing',
      manual: 'https://drive.google.com/file/d/1AIJuAdYrCFohbFCh72cgjoYdwnoQqPh_/view?usp=sharing' /* Gemelo digital de riego - Manual de uso.pdf */ }
];
var TEXTO_T1 = '¿Dudas con esta pantalla?';
var TEXTO_BTN = 'Ver vídeo tutorial';
var TEXTO_MANUAL = 'Manual PDF';

var destruido = false;
var aviso = null;
var overlay = null;
var onKey = null;
var lista = VIDEOS;

var ESTILO_ID = 'kv-tutorial-estilo-v2';
var CSS =
    // ---- aviso flotante ----
    '.kv-tutorial{position:fixed;right:24px;bottom:24px;top:auto;z-index:1150;display:flex;align-items:center;gap:14px;' +
    'max-width:calc(100vw - 48px);box-sizing:border-box;padding:12px 12px 12px 16px;background:#ffffff;border-radius:10px;' +
    'border-left:5px solid #2E7D5B;box-shadow:0 10px 30px rgba(0,0,0,.22);font-family:Mulish,Roboto,sans-serif;color:#3F3530;' +
    'transform:translateY(16px);opacity:0;transition:transform .3s ease,opacity .3s ease;}' +
    '.kv-tutorial.visible{transform:translateY(0);opacity:1;}' +
    '.kv-tutorial .kv-ic{width:38px;height:38px;border-radius:50%;background:#E6F3EC;display:flex;align-items:center;justify-content:center;flex-shrink:0;}' +
    '.kv-tutorial .kv-ic svg{width:20px;height:20px;}' +
    '.kv-tutorial .kv-tx{display:flex;flex-direction:column;min-width:0;}' +
    '.kv-tutorial .kv-t1{font-weight:800;font-size:14px;color:#2E7D5B;}' +
    '.kv-tutorial .kv-t2{font-size:12.5px;color:#786F68;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;}' +
    '.kv-tutorial .kv-btn{border:0;cursor:pointer;background:#2E7D5B;color:#fff;font:700 13px Mulish,Roboto,sans-serif;' +
    'padding:9px 14px;border-radius:7px;white-space:nowrap;transition:background .2s ease;display:inline-flex;align-items:center;gap:6px;}' +
    '.kv-tutorial .kv-btn:hover{background:#226448;}' +
    '.kv-tutorial .kv-pdf,.kv-vt-pdf{border:1.5px solid #2E7D5B;cursor:pointer;background:#ffffff;color:#2E7D5B;font:700 13px Mulish,Roboto,sans-serif;' +
    'padding:7.5px 12px;border-radius:7px;white-space:nowrap;text-decoration:none;display:inline-flex;align-items:center;gap:6px;transition:background .2s ease;}' +
    '.kv-tutorial .kv-pdf:hover,.kv-vt-pdf:hover{background:#E6F3EC;}' +
    '.kv-tutorial .kv-pdf svg,.kv-vt-pdf svg{width:15px;height:15px;}' +
    '.kv-vt-acc{display:flex;align-items:center;gap:8px;}' +
    '.kv-tutorial .kv-x{border:0;background:transparent;cursor:pointer;color:#A39A93;font-size:18px;line-height:1;padding:4px 6px;border-radius:6px;}' +
    '.kv-tutorial .kv-x:hover{background:#F2EFEC;color:#3F3530;}' +
    // ---- versión minimizada: botón redondo ----
    '.kv-tutorial.min{padding:0;gap:0;border-left:0;border-radius:50%;width:52px;height:52px;justify-content:center;background:#2E7D5B;cursor:pointer;}' +
    '.kv-tutorial.min .kv-ic{background:transparent;width:52px;height:52px;}' +
    '.kv-tutorial.min .kv-ic svg circle{fill:#ffffff;}' +
    '.kv-tutorial.min .kv-ic svg path{fill:#2E7D5B;}' +
    '.kv-tutorial.min .kv-tx,.kv-tutorial.min .kv-btn,.kv-tutorial.min .kv-pdf,.kv-tutorial.min .kv-x{display:none;}' +
    '.kv-tutorial.min:hover{background:#226448;}' +
    // ---- ventana del vídeo ----
    '.kv-vt-ov{position:fixed;inset:0;z-index:100000;background:rgba(20,16,14,.78);display:flex;align-items:center;justify-content:center;' +
    'padding:24px;box-sizing:border-box;opacity:0;transition:opacity .2s ease;font-family:Mulish,Roboto,sans-serif;}' +
    '.kv-vt-ov.visible{opacity:1;}' +
    '.kv-vt-modal{width:min(1280px,100%);background:#ffffff;border-radius:12px;overflow:hidden;box-shadow:0 24px 60px rgba(0,0,0,.45);' +
    'transform:scale(.97);transition:transform .2s ease;}' +
    '.kv-vt-ov.visible .kv-vt-modal{transform:scale(1);}' +
    '.kv-vt-head{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:10px 10px 10px 16px;border-bottom:1px solid #EEE9E5;}' +
    '.kv-vt-tabs{display:flex;gap:6px;flex-wrap:wrap;}' +
    '.kv-vt-tab{border:0;background:transparent;color:#786F68;font:700 14px Mulish,Roboto,sans-serif;padding:8px 12px;border-radius:7px;cursor:pointer;}' +
    '.kv-vt-tab:hover{background:#F2EFEC;color:#3F3530;}' +
    '.kv-vt-tab.act{background:#E6F3EC;color:#2E7D5B;}' +
    '.kv-vt-tab.solo{cursor:default;background:transparent;color:#3F3530;font-size:15px;}' +
    '.kv-vt-x{border:0;background:transparent;cursor:pointer;color:#A39A93;font-size:26px;line-height:1;width:38px;height:38px;border-radius:7px;}' +
    '.kv-vt-x:hover{background:#F2EFEC;color:#3F3530;}' +
    '.kv-vt-player{position:relative;width:100%;aspect-ratio:16/9;max-height:calc(100vh - 120px);background:#000;}' +
    '.kv-vt-player video,.kv-vt-player iframe{position:absolute;inset:0;width:100%;height:100%;border:0;background:#000;}' +
    '.kv-vt-err{position:absolute;inset:0;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:10px;padding:32px;text-align:center;color:#eee;font-size:15px;}' +
    '.kv-vt-err b{font-size:20px;color:#fff;}' +
    '.kv-vt-err code{background:rgba(255,255,255,.1);padding:6px 10px;border-radius:6px;font-size:13px;word-break:break-all;color:#ffd27a;}' +
    '@media (max-width:600px){.kv-tutorial:not(.min){left:12px;right:12px;bottom:12px;max-width:none;flex-wrap:wrap;}.kv-tutorial .kv-t2{white-space:normal;}' +
    '.kv-tutorial:not(.min) .kv-tx{flex:1 1 60%;}' +
    '.kv-tutorial:not(.min){padding-right:36px;}.kv-tutorial:not(.min) .kv-x{position:absolute;top:6px;right:6px;}' +
    '.kv-vt-ov{padding:8px;}}';

var ICONO = '<svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="12" r="11" fill="#2E7D5B"></circle>' +
    '<path d="M10 7.8v8.4l6.4-4.2z" fill="#ffffff"></path></svg>';

var ICONO_PDF = '<svg viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round">' +
    '<path d="M12 4v11"></path><path d="M7 10l5 5 5-5"></path><path d="M5 20h14"></path></svg>';

// Enlace de descarga del PDF. Google Drive -> descarga directa del archivo.
function urlDescarga(url) {
    var u = String(url || '').trim();
    if (!u) return '';
    var m = u.match(/drive\.google\.com\/(?:file\/d\/|open\?id=|uc\?(?:[^#]*&)?id=)([\w-]+)/);
    if (m) return 'https://drive.google.com/uc?export=download&id=' + m[1];
    return u;
}
function botonManual(clase, url) {
    var a = document.createElement('a');
    a.className = clase;
    a.href = urlDescarga(url);
    a.target = '_blank';
    a.rel = 'noopener';
    a.setAttribute('download', '');
    a.title = 'Descargar el manual de uso en PDF';
    a.innerHTML = ICONO_PDF + '<span></span>';
    a.querySelector('span').textContent = TEXTO_MANUAL;
    a.addEventListener('click', function (e) { e.stopPropagation(); });
    return a;
}

function enDialogo() {
    var el = self.ctx.$container[0];
    while (el) {
        if (el.classList && (el.classList.contains('cdk-overlay-pane') || el.classList.contains('mat-mdc-dialog-container')
            || (el.tagName && el.tagName.toLowerCase() === 'mat-dialog-container'))) return true;
        el = el.parentElement;
    }
    return false;
}
function normalizar(t) {
    return String(t || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '');
}
// Limpia lo que guardaba la versión anterior (recordaba el minimizado)
function limpiarVersionAnterior() {
    try {
        for (var i = window.sessionStorage.length - 1; i >= 0; i--) {
            var k = window.sessionStorage.key(i);
            if (k && k.indexOf('kv-tutorial-min-') === 0) window.sessionStorage.removeItem(k);
        }
    } catch (e) { }
}

self.onInit = function () {
    if (enDialogo()) return;
    var st = document.getElementById(ESTILO_ID);
    if (!st) { st = document.createElement('style'); st.id = ESTILO_ID; document.head.appendChild(st); }
    st.textContent = CSS;
    limpiarVersionAnterior();

    var titulo = normalizar(self.ctx.widgetConfig && self.ctx.widgetConfig.title);
    var elegidos = VIDEOS.filter(function (v) { return v.clave && titulo.indexOf(normalizar(v.clave)) !== -1; });
    lista = elegidos.length ? elegidos : VIDEOS;
    crearAviso();
};

function crearAviso() {
    quitarAviso();
    aviso = document.createElement('div');
    aviso.className = 'kv-tutorial';
    aviso.innerHTML =
        '<div class="kv-ic">' + ICONO + '</div>' +
        '<div class="kv-tx"><span class="kv-t1"></span><span class="kv-t2"></span></div>' +
        '<button class="kv-btn" type="button">' + TEXTO_BTN + ' →</button>' +
        '<button class="kv-x" type="button" title="Minimizar">×</button>';
    aviso.querySelector('.kv-t1').textContent = TEXTO_T1;
    aviso.querySelector('.kv-t2').textContent = lista.length === 1 ? 'Tutorial: ' + lista[0].titulo : 'Tutoriales de la plataforma';
    aviso.querySelector('.kv-btn').addEventListener('click', function (e) { e.stopPropagation(); abrirVideo(0); });
    aviso.querySelector('.kv-x').addEventListener('click', function (e) { e.stopPropagation(); minimizar(true); });
    if (lista.length === 1 && urlDescarga(lista[0].manual)) {
        aviso.insertBefore(botonManual('kv-pdf', lista[0].manual), aviso.querySelector('.kv-x'));
    }
    aviso.addEventListener('click', function () { if (aviso.classList.contains('min')) abrirVideo(0); });
    document.body.appendChild(aviso);
    setTimeout(function () { if (aviso) aviso.classList.add('visible'); }, 30);
}
function minimizar(si) {
    if (!aviso) return;
    aviso.classList.toggle('min', si);
    aviso.title = si ? TEXTO_BTN : '';
}
function quitarAviso() {
    if (aviso && aviso.parentNode) aviso.parentNode.removeChild(aviso);
    aviso = null;
}

function urlEmbebida(url) {
    var m = url.match(/(?:youtu\.be\/|youtube\.com\/(?:watch\?v=|embed\/|shorts\/))([\w-]{11})/);
    if (m) return { tipo: 'iframe', src: 'https://www.youtube-nocookie.com/embed/' + m[1] + '?autoplay=1&rel=0' };
    m = url.match(/drive\.google\.com\/file\/d\/([\w-]+)/);
    if (m) return { tipo: 'iframe', src: 'https://drive.google.com/file/d/' + m[1] + '/preview' };
    m = url.match(/vimeo\.com\/(\d+)/);
    if (m) return { tipo: 'iframe', src: 'https://player.vimeo.com/video/' + m[1] + '?autoplay=1' };
    return { tipo: 'video', src: url };
}

function abrirVideo(i) {
    cerrarVideo();
    overlay = document.createElement('div');
    overlay.className = 'kv-vt-ov';
    overlay.innerHTML =
        '<div class="kv-vt-modal" role="dialog" aria-modal="true">' +
        '<div class="kv-vt-head"><div class="kv-vt-tabs"></div><div class="kv-vt-acc"><button class="kv-vt-x" type="button" aria-label="Cerrar">×</button></div></div>' +
        '<div class="kv-vt-player"></div></div>';
    var tabs = overlay.querySelector('.kv-vt-tabs');
    lista.forEach(function (v, k) {
        var t = document.createElement(lista.length > 1 ? 'button' : 'span');
        t.className = 'kv-vt-tab' + (lista.length === 1 ? ' solo' : '');
        t.textContent = v.titulo;
        if (lista.length > 1) t.addEventListener('click', function () { mostrar(k); });
        tabs.appendChild(t);
    });
    overlay.querySelector('.kv-vt-x').addEventListener('click', cerrarVideo);
    overlay.addEventListener('click', function (e) { if (e.target === overlay) cerrarVideo(); });
    onKey = function (e) { if (e.key === 'Escape') cerrarVideo(); };
    document.addEventListener('keydown', onKey);
    document.body.appendChild(overlay);
    mostrar(i);
    setTimeout(function () { if (overlay) overlay.classList.add('visible'); }, 20);
}
function mostrar(i) {
    if (!overlay) return;
    var player = overlay.querySelector('.kv-vt-player');
    player.innerHTML = '';
    var e = urlEmbebida(lista[i].url), el;
    if (e.tipo === 'iframe') {
        el = document.createElement('iframe');
        el.src = e.src;
        el.allow = 'autoplay; fullscreen; picture-in-picture';
        el.allowFullscreen = true;
    } else {
        el = document.createElement('video');
        el.src = e.src; el.controls = true; el.autoplay = true; el.playsInline = true;
        el.addEventListener('error', function () {
            player.innerHTML = '<div class="kv-vt-err"><b>No se ha podido cargar el vídeo.</b>' +
                '<span>Revisa que la dirección sea la del archivo (o un enlace de YouTube o Google Drive) y que no pida iniciar sesión.</span><code></code></div>';
            player.querySelector('code').textContent = lista[i].url;
        });
    }
    player.appendChild(el);
    overlay.querySelectorAll('.kv-vt-tab').forEach(function (t, k) { t.classList.toggle('act', k === i); });
    // botón del manual del vídeo que se está viendo
    var acc = overlay.querySelector('.kv-vt-acc');
    var viejo = acc.querySelector('.kv-vt-pdf');
    if (viejo) acc.removeChild(viejo);
    if (urlDescarga(lista[i].manual)) acc.insertBefore(botonManual('kv-vt-pdf', lista[i].manual), acc.querySelector('.kv-vt-x'));
}
function cerrarVideo() {
    if (overlay && overlay.parentNode) overlay.parentNode.removeChild(overlay);
    overlay = null;
    if (onKey) { document.removeEventListener('keydown', onKey); onKey = null; }
}

self.onResize = function () {};
self.onDestroy = function () {
    destruido = true;
    cerrarVideo();
    quitarAviso();
};
self.typeParameters = function () {
    return { dataKeysOptional: true, datasourcesOptional: true, hasDataExportAction: false, embedTitlePanel: false };
};
